#include "soft_renderer.hpp"
#include <chrono>
#include <cstdio>
#include <cstring>
using namespace soft;
int main(int argc,char**argv){bool coverage=true,partial=false,prepared=true,advance=false,tables=true,batch=true;for(int i=1;i<argc;++i){if(!strcmp(argv[i],"--no-coverage"))coverage=false;if(!strcmp(argv[i],"--partial-alpha"))partial=true;if(!strcmp(argv[i],"--generic"))prepared=false;if(!strcmp(argv[i],"--advance"))advance=true;if(!strcmp(argv[i],"--no-tables"))tables=false;if(!strcmp(argv[i],"--no-batch-counters"))batch=false;}Texture t;t.width=t.height=64;t.pixels.resize(4096);t.alpha.assign(4096,255);for(unsigned i=0;i<4096;++i)t.pixels[i]=rgb(i%256,(i/16)%256,i*13%256);for(bool gradient:{false,true}){Renderer r;r.nearestCoverageEnabled(coverage);r.batchGeneralCountersEnabled(true);r.batchCountersEnabled(batch);r.preparedWorldEnabled(prepared);r.modulationTablesEnabled(tables);r.exactAdvanceEnabled(advance);Camera c;c.position={0,0,0};ScreenState s;s.zTest=s.zWrite=true;s.blend=1;ShadedVertex a[3]={{{-4,-3,5},{0,1},170,190,160,255},{{4,-3,8},{1,1},170,190,160,255},{{-4,3,5},{0,0},170,190,160,255}},b[3]={a[2],a[1],{{4,3,8},{1,0},170,190,160,255}};if(partial){for(auto& v:a)v.a=140;for(auto& v:b)v.a=140;s.zWrite=false;}if(gradient){a[1].r=b[1].r=b[2].r=220;a[2].g=b[0].g=100;}auto start=std::chrono::steady_clock::now();for(int f=0;f<1000;++f){r.clear(0);r.shadedTriangle(a,&t,s,c);r.shadedTriangle(b,&t,s,c);}unsigned long long hash=1469598103934665603ull;for(auto p:r.pixels()){hash^=p;hash*=1099511628211ull;}printf("opaque world prepared=%d advance=%d tables=%d blend=1 gradient=%d %.4f ms/frame hash=%llx coverage=%d certified=%llu partial=%d\n",prepared,advance,tables,gradient,std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count()/1000,hash,coverage,(unsigned long long)r.stats().nearestCoveragePixels,partial);}}
